mapper.select:
SELECT JSON_UNQUOTE(JSON_EXTRACT(content_json,'$.responsibility')) AS responsibility,
  JSON_EXTRACT(content_json,'$.source') AS source_json
FROM preparation_version WHERE owner_id=#{owner} AND item_id=#{itemId} AND id=#{versionId}

SELECT d.task_id,d.target_project_id,d.target_item_id,d.target_version_id,
  v.version_number AS target_version_number,d.created_at AS adopted_at,t.purpose,t.status AS task_status,
  t.manifest_json,t.manifest_hash,(t.candidate_json IS NOT NULL) AS candidate_present,
  t.created_at AS task_created_at,t.updated_at AS task_updated_at
FROM ai_fact_draft_decision d
JOIN preparation_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id
WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND d.status='ADOPTED' AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}
